/// lpapp — BOOK COMPANION (owner-approved screen 4).
///
/// The user practises from his OWN printed book: picks book (10 → latest),
/// test, section; runs the real exam timer; fills the on-screen OMR answer
/// sheet; then types the answer key from his own book; the phone marks it
/// (raw → band with the public table) and names the mistake types
/// (spelling, plural, word limit, T/F/NG, map, matching). Writing and
/// Speaking answers to book prompts are AI-scored (lp_score.dart).
/// NOTHING from the book is stored, shipped or generated by the app — the
/// footer says so. Each cell is max 40 characters (an answer, never a text).
library;

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';

import '../../l10n/app_localizations.dart';
import '../../state.dart';
import '../../theme.dart';
import '../../widgets/app_sheet.dart' show withNavBarInset;
import '../../widgets/local_digits.dart';
import '../../widgets/num_input.dart' show parseIntInput, LatinDigitsFormatter;
import 'lp_data.dart';
import 'lp_engine.dart';
import 'lp_score.dart';
import 'lp_ui.dart';

const int kLpFirstBook = 10;
const int kLpLatestBook = 20;

class LpCompanionScreen extends StatefulWidget {
  /// Gallery/tests: a finished sheet (answers, key) shown as marked.
  final Map<int, String>? debugAnswers, debugKey;
  const LpCompanionScreen({super.key, this.debugAnswers, this.debugKey});
  @override
  State<LpCompanionScreen> createState() => _LpCompanionScreenState();
}

enum _Phase { answer, key, result }

class _LpCompanionScreenState extends State<LpCompanionScreen> {
  int _book = kLpLatestBook, _test = 1;
  String _section = 'listening', _variant = 'academic';
  _Phase _phase = _Phase.answer;
  bool _running = false, _started = false;
  int _timerKey = 0, _left = 1800;
  int _wordLimit = 0;
  final _mapFrom = TextEditingController(), _mapTo = TextEditingController();
  final Map<int, TextEditingController> _a = {}, _k = {};
  OmrResult? _res;
  final DateTime _opened = DateTime.now();
  List<int> _books = [for (var b = kLpLatestBook; b >= kLpFirstBook; b--) b];

  int get _questions => 40;
  int get _duration => _section == 'listening' ? 1800 : 3600;

  TextEditingController _ctl(Map<int, TextEditingController> m, int n) => m.putIfAbsent(n, TextEditingController.new);

  @override
  void initState() {
    super.initState();
    _left = _duration;
    if (widget.debugAnswers != null && widget.debugKey != null) {
      widget.debugAnswers!.forEach((n, v) => _ctl(_a, n).text = v);
      widget.debugKey!.forEach((n, v) => _ctl(_k, n).text = v);
      _started = true;
      _left = 1800 - 1712;
      _markLocal();
    }
    unawaited(_loadBooks());
  }

  Future<void> _loadBooks() async {
    try {
      final r = await context.read<AppState>().api.getJson('/lp/companion/books');
      final b = (r['books'] as List?)?.whereType<num>().map((e) => e.toInt()).toList();
      if (b != null && b.isNotEmpty && mounted) {
        setState(() {
          _books = b..sort((x, y) => y.compareTo(x));
          if (!_books.contains(_book)) _book = _books.first;
        });
      }
    } catch (_) {
      // offline / not deployed: the built-in book list (10 → latest) stays
    }
  }

  @override
  void dispose() {
    for (final c in [..._a.values, ..._k.values, _mapFrom, _mapTo]) {
      c.dispose();
    }
    super.dispose();
  }

  void _reset() {
    setState(() {
      for (final c in [..._a.values, ..._k.values]) {
        c.clear();
      }
      _res = null;
      _phase = _Phase.answer;
      _running = false;
      _started = false;
      _timerKey++;
      _left = _duration;
    });
  }

  void _markLocal() {
    final ans = {for (final e in _a.entries) e.key: e.value.text};
    final key = {for (final e in _k.entries) e.key: e.value.text};
    _res = markSheet(_section, _variant, ans, key,
        wordLimit: _wordLimit, mapFrom: parseIntInput(_mapFrom.text), mapTo: parseIntInput(_mapTo.text));
    _phase = _Phase.result;
    _running = false;
  }

  void _mark() {
    final tr = AppLocalizations.of(context);
    if (_k.values.where((c) => c.text.trim().isNotEmpty).isEmpty) {
      lpToast(context, tr.lp2KeyNeeded);
      return;
    }
    setState(_markLocal);
    final api = context.read<AppState>().api;
    // save the user's own sheet (answers + the key he typed) for his history
    unawaited(() async {
      try {
        await api.postJson('/lp/companion/mark', {
          'book': _book,
          'test': _test,
          'section': _section,
          'variant': _variant,
          'answers': {for (final e in _a.entries) if (e.value.text.trim().isNotEmpty) '${e.key}': e.value.text.trim()},
          'key': {for (final e in _k.entries) if (e.value.text.trim().isNotEmpty) '${e.key}': e.value.text.trim()},
        });
      } catch (_) {
        // best-effort: history copy only; the marked sheet is already on screen
      }
    }());
    unawaited(lpLogPractice(api, 'book', DateTime.now().difference(_opened).inMinutes.clamp(1, 90)));
  }

  @override
  Widget build(BuildContext context) {
    final tr = AppLocalizations.of(context);
    final scheme = Theme.of(context).colorScheme;
    final res = _res;
    return Scaffold(
      appBar: AppBar(title: Text(tr.lp2BookCompanion)),
      body: ListView(
        padding: withNavBarInset(context, const EdgeInsets.fromLTRB(Gap.lg, Gap.md, Gap.lg, Gap.xxl)),
        children: [
          // ---- book · test · section
          Row(children: [
            Expanded(
              child: DropdownButtonFormField<int>(
                key: const Key('lp2-book'),
                initialValue: _book,
                isExpanded: true,
                decoration: InputDecoration(labelText: tr.lp2Book, border: const OutlineInputBorder()),
                items: [for (final b in _books) DropdownMenuItem(value: b, child: Text(tr.lp2BookN(ld(context, b))))],
                onChanged: _phase == _Phase.answer && !_started ? (v) => setState(() => _book = v ?? _book) : null,
              ),
            ),
            const SizedBox(width: Gap.sm),
            Expanded(
              child: DropdownButtonFormField<int>(
                key: const Key('lp2-test'),
                initialValue: _test,
                isExpanded: true,
                decoration: InputDecoration(labelText: tr.lp2Test, border: const OutlineInputBorder()),
                items: [for (var t = 1; t <= 4; t++) DropdownMenuItem(value: t, child: Text(tr.lp2TestN(ld(context, t))))],
                onChanged: _phase == _Phase.answer && !_started ? (v) => setState(() => _test = v ?? _test) : null,
              ),
            ),
          ]),
          const SizedBox(height: Gap.sm),
          Wrap(spacing: Gap.sm, runSpacing: Gap.sm, children: [
            for (final s in ['listening', 'reading'])
              ChoiceChip(
                label: Text(lpSectionName(tr, s)),
                selected: _section == s,
                onSelected: _started
                    ? null
                    : (_) => setState(() {
                          _section = s;
                          _left = _duration;
                          _timerKey++;
                        }),
              ),
            if (_section == 'reading')
              for (final v in ['academic', 'general'])
                ChoiceChip(
                  label: Text(v == 'academic' ? tr.lp2Academic : tr.lp2General),
                  selected: _variant == v,
                  onSelected: _phase == _Phase.result ? null : (_) => setState(() => _variant = v),
                ),
          ]),
          const SizedBox(height: Gap.md),
          // ---- timer
          Card(
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: Gap.md, vertical: Gap.sm),
              child: Row(children: [
                Expanded(child: Text(tr.lp2ExamTimer(ld(context, _duration ~/ 60)), style: const TextStyle(fontWeight: FontWeight.w600))),
                if (_started)
                  LpTimer(
                    key: ValueKey('ct$_timerKey'),
                    seconds: _left,
                    paused: !_running,
                    onTick: (l) => _left = l,
                    onDone: () {
                      if (!mounted) return;
                      lpToast(context, tr.lp2TimeUp);
                      setState(() {
                        _running = false;
                        _phase = _Phase.key;
                      });
                    },
                  ),
                if (_phase == _Phase.answer)
                  IconButton(
                    key: const Key('lp2-timer-btn'),
                    tooltip: _running ? tr.lp2Pause : tr.lp2StartTimer,
                    constraints: const BoxConstraints(minWidth: kMinTap, minHeight: kMinTap),
                    onPressed: () => setState(() {
                      _started = true;
                      _running = !_running;
                    }),
                    icon: Icon(_running ? Icons.pause_rounded : Icons.play_arrow_rounded),
                  ),
              ]),
            ),
          ),
          if (res != null) ...[
            const SizedBox(height: Gap.sm),
            _ScoreCard(res: res, section: _section),
          ],
          const SizedBox(height: Gap.md),
          // ---- step hint
          Text(
              switch (_phase) {
                _Phase.answer => tr.lp2OmrStepAnswer,
                _Phase.key => tr.lp2OmrStepKey,
                _Phase.result => tr.lp2OmrStepResult,
              },
              style: TextStyle(color: scheme.onSurfaceVariant, height: 1.4)),
          if (_phase == _Phase.key) ...[
            const SizedBox(height: Gap.sm),
            Wrap(spacing: Gap.sm, runSpacing: Gap.sm, crossAxisAlignment: WrapCrossAlignment.center, children: [
              Text(tr.lp2WordLimit),
              for (final w in [0, 1, 2, 3])
                ChoiceChip(
                  label: Text(w == 0 ? tr.lp2NoLimit : ld(context, w)),
                  selected: _wordLimit == w,
                  onSelected: (_) => setState(() => _wordLimit = w),
                ),
            ]),
            if (_section == 'listening')
              Padding(
                padding: const EdgeInsets.only(top: Gap.sm),
                child: Row(children: [
                  Expanded(child: Text(tr.lp2MapRange)),
                  SizedBox(width: 64, child: _numField(_mapFrom, tr.lp2From)),
                  const SizedBox(width: Gap.sm),
                  SizedBox(width: 64, child: _numField(_mapTo, tr.lp2To)),
                ]),
              ),
          ],
          const SizedBox(height: Gap.md),
          // ---- OMR grid
          LayoutBuilder(builder: (context, c) {
            final cols = c.maxWidth >= 560 ? 4 : 2;
            final w = (c.maxWidth - Gap.sm * (cols - 1)) / cols;
            return Wrap(
              key: const Key('lp2-omr'),
              spacing: Gap.sm,
              runSpacing: Gap.sm,
              children: [
                for (var n = 1; n <= _questions; n++) SizedBox(width: w, child: _cell(context, n)),
              ],
            );
          }),
          const SizedBox(height: Gap.lg),
          switch (_phase) {
            _Phase.answer => FilledButton.icon(
                key: const Key('lp2-to-key'),
                style: FilledButton.styleFrom(minimumSize: const Size.fromHeight(52)),
                onPressed: () => setState(() {
                  _running = false;
                  _phase = _Phase.key;
                }),
                icon: const Icon(Icons.key_rounded),
                label: Text(tr.lp2EnterKey),
              ),
            _Phase.key => FilledButton.icon(
                key: const Key('lp2-mark'),
                style: FilledButton.styleFrom(minimumSize: const Size.fromHeight(52)),
                onPressed: _mark,
                icon: const Icon(Icons.fact_check_rounded),
                label: Text(tr.lp2MarkSheet),
              ),
            _Phase.result => FilledButton.tonalIcon(
                style: FilledButton.styleFrom(minimumSize: const Size.fromHeight(52)),
                onPressed: _reset,
                icon: const Icon(Icons.add_rounded),
                label: Text(tr.lp2NewSheet),
              ),
          },
          const SizedBox(height: Gap.lg),
          Text(tr.lp2BookWS, style: const TextStyle(fontWeight: FontWeight.w700)),
          const SizedBox(height: Gap.sm),
          Wrap(spacing: Gap.sm, runSpacing: Gap.sm, children: [
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(minimumSize: const Size(kMinTap, kMinTap)),
              onPressed: () => Navigator.of(context)
                  .push(MaterialPageRoute(builder: (_) => const LpAiScoreScreen(kind: 'writing'))),
              icon: const Icon(Icons.edit_note_rounded),
              label: Text(tr.lp2ScoreWriting),
            ),
            OutlinedButton.icon(
              style: OutlinedButton.styleFrom(minimumSize: const Size(kMinTap, kMinTap)),
              onPressed: () => Navigator.of(context)
                  .push(MaterialPageRoute(builder: (_) => const LpAiScoreScreen(kind: 'speaking'))),
              icon: const Icon(Icons.record_voice_over_rounded),
              label: Text(tr.lp2ScoreSpeaking),
            ),
          ]),
          LpPracticeFooter(key: const Key('lp2-nocontent'), text: tr.lp2NoContentLine, icon: Icons.lock_outline_rounded),
        ],
      ),
    );
  }

  Widget _numField(TextEditingController c, String hint) => TextField(
        controller: c,
        keyboardType: TextInputType.number,
        inputFormatters: [const LatinDigitsFormatter(), FilteringTextInputFormatter.digitsOnly, LengthLimitingTextInputFormatter(2)],
        decoration: InputDecoration(isDense: true, hintText: hint, border: const OutlineInputBorder()),
      );

  Widget _cell(BuildContext context, int n) {
    final tr = AppLocalizations.of(context);
    final scheme = Theme.of(context).colorScheme;
    final m = _res?.mistakes;
    final marked = m != null && m.containsKey(n);
    final ok = marked && m[n] == null;
    final colour = !marked ? scheme.outlineVariant : (ok ? Brand.success : Brand.danger);
    final field = _phase == _Phase.key ? _ctl(_k, n) : _ctl(_a, n);
    return Container(
      padding: const EdgeInsets.all(Gap.xs),
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: colour, width: marked ? 2 : 1),
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(children: [
          CircleAvatar(
            radius: 13,
            backgroundColor: marked ? colour.withValues(alpha: 0.2) : scheme.surfaceContainerHighest,
            child: Text(ld(context, n), style: AType.bodySmall.copyWith(fontWeight: FontWeight.w700)),
          ),
          const SizedBox(width: Gap.xs),
          Expanded(
            child: _phase == _Phase.result
                ? Text(_ctl(_a, n).text.isEmpty ? '—' : _ctl(_a, n).text, overflow: TextOverflow.ellipsis)
                : TextField(
                    key: Key('lp2-${_phase == _Phase.key ? 'k' : 'a'}$n'),
                    controller: field,
                    inputFormatters: [LengthLimitingTextInputFormatter(40)],
                    textInputAction: TextInputAction.next,
                    decoration: InputDecoration(
                      isDense: true,
                      hintText: _phase == _Phase.key ? tr.lp2KeyHint : null,
                      border: InputBorder.none,
                    ),
                  ),
          ),
          if (marked)
            Icon(ok ? Icons.check_rounded : Icons.close_rounded, size: 18, color: Brand.onTint(context, colour)),
        ]),
        if (_phase == _Phase.key && _ctl(_a, n).text.isNotEmpty)
          Text(tr.lp2YouWrote(_ctl(_a, n).text),
              overflow: TextOverflow.ellipsis, style: AType.bodySmall.copyWith(color: scheme.onSurfaceVariant)),
        if (marked && !ok) ...[
          Text(tr.lp2KeyWas(_ctl(_k, n).text), overflow: TextOverflow.ellipsis, style: AType.bodySmall),
          Text(lpMistakeName(tr, m[n]!),
              style: AType.bodySmall.copyWith(color: Brand.onTint(context, Brand.danger), fontWeight: FontWeight.w700)),
        ],
      ]),
    );
  }
}

class _ScoreCard extends StatelessWidget {
  final OmrResult res;
  final String section;
  const _ScoreCard({required this.res, required this.section});
  @override
  Widget build(BuildContext context) {
    final tr = AppLocalizations.of(context);
    final scheme = Theme.of(context).colorScheme;
    final counts = res.counts.entries.toList()..sort((a, b) => b.value.compareTo(a.value));
    return Card(
      key: const Key('lp2-omr-score'),
      color: scheme.primaryContainer,
      child: Padding(
        padding: const EdgeInsets.all(Gap.md),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [
            Expanded(
              child: Text(tr.lp2RawScore(ld(context, res.raw), ld(context, res.total)),
                  style: TextStyle(fontWeight: FontWeight.w700, color: scheme.onPrimaryContainer)),
            ),
            Text(tr.lp2BandIs(ld(context, bandText(res.band))),
                style: Theme.of(context)
                    .textTheme
                    .headlineSmall
                    ?.copyWith(fontWeight: FontWeight.w800, color: scheme.onPrimaryContainer)),
          ]),
          if (res.total != 40)
            Text(tr.lp2ScaledNote(ld(context, res.total)),
                style: AType.bodySmall.copyWith(color: scheme.onPrimaryContainer)),
          if (counts.isNotEmpty) ...[
            const SizedBox(height: Gap.sm),
            Text(tr.lp2MistakeTypes, style: TextStyle(fontWeight: FontWeight.w700, color: scheme.onPrimaryContainer)),
            for (final e in counts)
              Padding(
                padding: const EdgeInsets.only(top: Gap.xs),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Text('${lpMistakeName(tr, e.key)} · ${ld(context, e.value)}',
                      style: TextStyle(fontWeight: FontWeight.w600, color: scheme.onPrimaryContainer)),
                  Text(lpMistakeTip(tr, e.key),
                      style: AType.bodySmall.copyWith(color: scheme.onPrimaryContainer, height: 1.35)),
                ]),
              ),
          ],
          const LpPracticeFooter(),
        ]),
      ),
    );
  }
}
